import React, { useState, useEffect } from 'react';
import './sunsetPredictor.css';

const DEFAULT_LOCATION = {
  latitude: 30.2672,
  longitude: -97.7431,
  location_name: 'Austin, TX',
};

const scoreTone = (score) => {
  if (score >= 8.5) return 'exceptional';
  if (score >= 7) return 'excellent';
  if (score >= 5.5) return 'good';
  if (score >= 4) return 'fair';
  return 'muted';
};

const generateSunsetGradient = (hue, saturation, brightness) => {
  if (hue == null) return 'linear-gradient(165deg, #1a1423 0%, #3d2a1f 45%, #c45c26 100%)';

  const h = ((hue % 360) + 360) % 360 / 360;
  const s = Math.min(Math.max(saturation ?? 0.6, 0), 1);
  const b = Math.min(Math.max(brightness ?? 0.7, 0), 1);

  const c = b * s;
  const x = c * (1 - Math.abs((h * 6) % 2 - 1));
  const m = b - c;

  let r, g, bl;
  if (h < 1 / 6) [r, g, bl] = [c, x, 0];
  else if (h < 2 / 6) [r, g, bl] = [x, c, 0];
  else if (h < 3 / 6) [r, g, bl] = [0, c, x];
  else if (h < 4 / 6) [r, g, bl] = [0, x, c];
  else if (h < 5 / 6) [r, g, bl] = [x, 0, c];
  else [r, g, bl] = [c, 0, x];

  const toHex = (n) => {
    const hex = Math.round((n + m) * 255).toString(16);
    return hex.length === 1 ? `0${hex}` : hex;
  };

  const top = `#${toHex(r)}${toHex(g)}${toHex(bl)}`;
  return `linear-gradient(165deg, #140f1a 0%, #2a1a28 40%, ${top} 100%)`;
};

const SunsetPredictor = () => {
  const [location, setLocation] = useState(DEFAULT_LOCATION);
  const [week, setWeek] = useState(null);
  const [selectedDate, setSelectedDate] = useState(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);

  const selected = week?.days?.find((d) => d.date === selectedDate) || week?.days?.[0];

  const loadWeek = async (loc = location) => {
    setLoading(true);
    setError(null);
    try {
      const response = await fetch('http://localhost:5001/api/week', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          latitude: Number(loc.latitude),
          longitude: Number(loc.longitude),
          location_name: loc.location_name || 'Custom location',
          days: 7,
        }),
      });
      const data = await response.json();
      if (!response.ok) {
        throw new Error(data.error || `API error: ${response.status}`);
      }
      setWeek(data);
      const best = data.best_day?.date || data.days?.[0]?.date;
      setSelectedDate(best);
    } catch (err) {
      setError(err.message);
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    loadWeek(DEFAULT_LOCATION);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const handleLocationSubmit = (e) => {
    e.preventDefault();
    loadWeek(location);
  };

  return (
    <div className="sunset-predictor">
      <header className="sky-hero" style={{
        background: selected
          ? generateSunsetGradient(
              selected.prediction.hue_shift,
              selected.prediction.saturation,
              selected.prediction.brightness
            )
          : undefined,
      }}>
        <div className="sky-hero-inner">
          <p className="brand">SunPredictor</p>
          <h1>This week&apos;s sunsets</h1>
          <p className="lede">
            Live forecast weather near sunset, scored 1–10 by your ML model.
          </p>
          {selected && (
            <div className="hero-score">
              <span className={`score-pill ${scoreTone(selected.aesthetic_score)}`}>
                {selected.aesthetic_score}
                <span>/10</span>
              </span>
              <div className="hero-score-meta">
                <strong>{selected.weekday}</strong>
                <span>{selected.aesthetic_label} · sunset {selected.sunset_time || '—'}</span>
              </div>
            </div>
          )}
        </div>
      </header>

      <main className="week-main">
        <form className="location-bar" onSubmit={handleLocationSubmit}>
          <label>
            Place
            <input
              type="text"
              value={location.location_name}
              onChange={(e) => setLocation((p) => ({ ...p, location_name: e.target.value }))}
              placeholder="Austin, TX"
            />
          </label>
          <label>
            Lat
            <input
              type="number"
              step="0.0001"
              value={location.latitude}
              onChange={(e) => setLocation((p) => ({ ...p, latitude: e.target.value }))}
            />
          </label>
          <label>
            Lon
            <input
              type="number"
              step="0.0001"
              value={location.longitude}
              onChange={(e) => setLocation((p) => ({ ...p, longitude: e.target.value }))}
            />
          </label>
          <button type="submit" disabled={loading}>
            {loading ? 'Loading…' : 'Forecast week'}
          </button>
        </form>

        {error && <div className="error-banner">{error}</div>}

        {week?.best_day && (
          <p className="best-callout">
            Best evening: <strong>{week.best_day.weekday}</strong> ({week.best_day.date}) —{' '}
            {week.best_day.aesthetic_score}/10 · {week.best_day.aesthetic_label}
          </p>
        )}

        <section className="week-strip" aria-label="Seven day sunset scores">
          {(week?.days || []).map((day) => (
            <button
              key={day.date}
              type="button"
              className={`day-chip ${selectedDate === day.date ? 'active' : ''} ${scoreTone(day.aesthetic_score)}`}
              onClick={() => setSelectedDate(day.date)}
            >
              <span className="day-name">{day.weekday.slice(0, 3)}</span>
              <span className="day-score">{day.aesthetic_score}</span>
              <span className="day-label">{day.aesthetic_label}</span>
            </button>
          ))}
          {!week && loading && (
            <p className="loading-note">Pulling Open-Meteo forecast…</p>
          )}
        </section>

        {selected && (
          <section className="day-detail">
            <div className="detail-copy">
              <h2>
                {selected.weekday}
                <span>{selected.date}</span>
              </h2>
              <p>{selected.visual_description}</p>
              <dl className="weather-facts">
                <div>
                  <dt>Clouds</dt>
                  <dd>{selected.weather.cloud_cover}%</dd>
                </div>
                <div>
                  <dt>Humidity</dt>
                  <dd>{selected.weather.humidity}%</dd>
                </div>
                <div>
                  <dt>Wind</dt>
                  <dd>{selected.weather.wind_speed} mph</dd>
                </div>
                <div>
                  <dt>Visibility</dt>
                  <dd>{selected.weather.visibility} km</dd>
                </div>
                <div>
                  <dt>Temp</dt>
                  <dd>{selected.weather.temperature}°F</dd>
                </div>
                <div>
                  <dt>Sunset</dt>
                  <dd>{selected.sunset_time || '—'}</dd>
                </div>
              </dl>
            </div>

            <div className="detail-metrics">
              <h3>ML visual outputs</h3>
              <ul>
                <li>
                  <span>Hue</span>
                  <strong>{Math.round(selected.prediction.hue_shift)}°</strong>
                </li>
                <li>
                  <span>Saturation</span>
                  <strong>{(selected.prediction.saturation * 100).toFixed(0)}%</strong>
                </li>
                <li>
                  <span>Brightness</span>
                  <strong>{(selected.prediction.brightness * 100).toFixed(0)}%</strong>
                </li>
                <li>
                  <span>Cloud density</span>
                  <strong>{(selected.prediction.cloud_density * 100).toFixed(0)}%</strong>
                </li>
              </ul>
              <p className="prompt-note">{selected.image_generation_prompt}</p>
            </div>
          </section>
        )}
      </main>
    </div>
  );
};

export default SunsetPredictor;
